using System.Text.Json;
using Dapper;
using Microsoft.AspNetCore.Mvc;
using Sanadi.Api.Security;
using Sanadi.Application.Security;
using Sanadi.Domain.Exceptions;
using Sanadi.Infrastructure.Persistence;

namespace Sanadi.Api.Controllers;

[ApiController]
[Route("api/owner")]
public sealed class OwnerController(ISqlConnectionFactory sql,IPermissionService permissions):ControllerBase
{
    private static readonly string[] Open=["submitted","acknowledged","classified","routed","assigned","in_progress","in_review","ai_processing","escalated","on_hold","waiting_external","awaiting_student","student_confirmation","reopened","transferred"];
    private static readonly string[] Progress=["assigned","in_progress","in_review","ai_processing","reopened"];
    private static readonly string[] Waiting=["awaiting_student","student_confirmation"];
    private Guid UserId(){var u=HttpContext.GetSanadiUser();if(!u.IsAuthenticated||u.UserId is not Guid id)throw new UnauthorizedException();return id;}
    private async Task<(Guid[] Units,string[] Roles,bool Manager,bool SeesAll)> Scope(Guid uid,Guid? requested,CancellationToken ct){var roles=(await permissions.GetRolesAsync(uid,ct)).ToArray();var manager=roles.Contains("system_admin")||roles.Contains("service_manager");await using var db=sql.Create();var ids=(await db.QueryAsync<Guid>(DbProc.Call("usp_Owner_ListStaffUnits", new{uid}, ct))).Distinct().ToList();var seesAll=manager&&ids.Count==0;if(seesAll)ids=(await db.QueryAsync<Guid>(DbProc.Call("usp_Owner_ListActiveUnits", null, ct))).ToList();if(requested is not null&&ids.Contains(requested.Value))ids=[requested.Value];return(ids.ToArray(),roles,manager,seesAll);}

    [HttpGet("workspace")]
    public async Task<object> Workspace(CancellationToken ct){var uid=UserId();var s=await Scope(uid,null,ct);await using var db=sql.Create();var units=await db.QueryAsync(DbProc.Call("usp_Owner_ListUnitsByIds", new{ids=DbProc.Csv(s.Units)}, ct));var perms=await db.QueryAsync(DbProc.Call("usp_Owner_ListActionPermissions", new{ids=DbProc.Csv(s.Units)}, ct));var actions=perms.GroupBy(x=>(string)x.service_unit_id.ToString()).ToDictionary(g=>g.Key,g=>g.ToArray());return new{units=units.Select(u=>new{u.id,u.code,u.nameEn,u.nameAr,ownershipType=s.SeesAll?"oversight":"assigned_staff",capabilities=Array.Empty<string>()}),roles=s.Roles,isOwner=s.Roles.Contains("service_owner"),isManager=s.Manager,seesAllUnits=s.SeesAll,actionsByUnit=actions};}

    private async Task<dynamic[]> Cases(Guid uid,Guid? unit,CancellationToken ct,bool recentOnly=false){var s=await Scope(uid,unit,ct);await using var db=sql.Create();var rows=await db.QueryAsync(DbProc.Call("usp_Owner_ListOpenCases", new{units=DbProc.Csv(s.Units),uid,open=DbProc.Csv(Open)}, ct));return rows.ToArray();}

    [HttpGet("overview")]
    public async Task<object> Overview([FromQuery]Guid? unitId,CancellationToken ct){var uid=UserId();var s=await Scope(uid,unitId,ct);var rows=await Cases(uid,unitId,ct);var now=DateTimeOffset.UtcNow;object Map(dynamic c){DateTimeOffset? due=c.resolution_due_at as DateTimeOffset?;bool attention=c.attention_category is not null||(c.automation_paused is bool p&&p);return new{id=c.id,case_number=c.case_number,case_type=c.case_type,title=c.title,status=c.status,urgency=c.urgency,is_sensitive=c.is_sensitive,service_unit_id=c.service_unit_id,assigned_to=c.assigned_to,created_at=c.created_at,last_activity_at=c.last_activity_at,resolution_due_at=c.resolution_due_at,routing_service_code=c.routing_service_code,routing_topic=c.routing_topic,root_cause_code=c.root_cause_code,routing_reason_en=c.routing_reason_en,routing_reason_ar=c.routing_reason_ar,routing_confidence=c.routing_confidence,automation=new{attention_category=c.attention_category,attention_reason_en=c.attention_reason_en,attention_reason_ar=c.attention_reason_ar,next_action_en=c.next_action_en,next_action_ar=c.next_action_ar,next_action_at=c.next_action_at,automation_paused=c.automation_paused},needsAttention=attention,breached=due is not null&&due<now,lowConfidenceRouting=(decimal?)(c.routing_confidence) is decimal conf&&conf<.6m};}var items=rows.Select(Map).ToArray();dynamic D(object x)=>x;var attention=items.Where(x=>(bool)D(x).needsAttention).ToArray();var ai=items.Where(x=>!(bool)D(x).needsAttention).ToArray();var breached=items.Count(x=>(bool)D(x).breached);return new{unitIds=s.Units,cases=items,attention,aiManaged=ai,recent=items.Take(8),counts=new{open=items.Length,attention=attention.Length,aiManaged=ai.Length,atRisk=0,breached,waitingStudent=rows.Count(x=>Waiting.Contains((string)x.status)),newToday=rows.Count(x=>((DateTimeOffset)x.created_at).Date==now.Date)}};}

    [HttpGet("insights")]
    public async Task<object> Insights([FromQuery]Guid? unitId,CancellationToken ct){var uid=UserId();var s=await Scope(uid,unitId,ct);await using var db=sql.Create();var rows=(await db.QueryAsync(DbProc.Call("usp_Owner_ListInsightCases", new{units=DbProc.Csv(s.Units)}, ct))).ToArray();object[] Tally(Func<dynamic,string?> get)=>rows.Select(get).Where(x=>!string.IsNullOrWhiteSpace(x)).GroupBy(x=>x!).OrderByDescending(g=>g.Count()).Take(5).Select(g=>(object)new{label=g.Key,count=g.Count()}).ToArray();var resolved=rows.Where(x=>x.resolved_at is not null).ToArray();var durations=resolved.Select(x=>((DateTimeOffset)x.resolved_at-(DateTimeOffset)x.created_at).TotalHours).ToArray();return new{totalCases=rows.Length,byType=Tally(x=>(string?)x.case_type).Select(x=>new{type=((dynamic)x).label,count=((dynamic)x).count}),automationRate=rows.Length==0?(int?)null:(int)Math.Round(rows.Count(x=>x.attention_category is null&&!(x.automation_paused is bool b&&b))*100d/rows.Length),slaCompliance=resolved.Length==0?(int?)null:(int)Math.Round(resolved.Count(x=>x.resolution_due_at is null||(DateTimeOffset)x.resolved_at<=(DateTimeOffset)x.resolution_due_at)*100d/resolved.Length),avgResolutionHours=durations.Length==0?(double?)null:Math.Round(durations.Average(),1),topTopics=Tally(x=>(string?)x.routing_topic),topRootCauses=Tally(x=>(string?)x.root_cause_code)};}

    [HttpGet("operations")]
    public async Task<object> Operations([FromQuery]Guid? unitId,CancellationToken ct){var uid=UserId();var rows=await Cases(uid,unitId,ct);await using var db=sql.Create();var students=rows.Select(x=>(Guid)x.student_id).Distinct().ToArray();var names=(await db.QueryAsync<(Guid Id,string Name)>(DbProc.Call("usp_Owner_ListProfileNames", new{students=DbProc.Csv(students)}, ct))).ToDictionary(x=>x.Id,x=>x.Name);var now=DateTimeOffset.UtcNow;var items=rows.Select(c=>{DateTimeOffset? due=c.resolution_due_at as DateTimeOffset?;double? hours=due is null?null:Math.Round((due.Value-now).TotalHours,1);string state=hours is null?"none":hours<0?"breached":hours<=8?"critical":hours<=24?"attention":"on_track";string responsible=Waiting.Contains((string)c.status)?"student":((string)c.status=="waiting_external"?"external":c.attention_category is not null?"owner":"ai");return new{id=c.id,caseNumber=c.case_number,title=c.title,status=c.status,urgency=c.urgency,caseType=c.case_type,studentName=names.GetValueOrDefault((Guid)c.student_id),unitNameEn=(string?)null,unitNameAr=(string?)null,lastActionEn=(string?)c.ai_status,lastActionAr=(string?)c.ai_status,nextActionEn=(string?)c.next_action_en,nextActionAr=(string?)c.next_action_ar,nextActionAt=c.next_action_at,dueAt=c.resolution_due_at,slaHours=hours,slaState=state,responsible,attentionCategory=(string?)c.attention_category};}).ToArray();dynamic D(object x)=>x;var overdue=items.Where(x=>(string)D(x).slaState=="breached").ToArray();var critical=items.Where(x=>(string)D(x).slaState=="critical").ToArray();var attention=items.Where(x=>(string)D(x).slaState=="attention").ToArray();return new{items,followUp=new{dueToday=Array.Empty<object>(),overdue,waitingStudent=items.Where(x=>(string)D(x).responsible=="student"),waitingExternal=items.Where(x=>(string)D(x).responsible=="external"),aiScheduled=items.Where(x=>(string)D(x).responsible=="ai"&&D(x).nextActionAt is not null),needsOwnerAction=items.Where(x=>(string)D(x).responsible=="owner")},sla=new{breached=overdue,critical,attention,onTrack=items.Count(x=>(string)D(x).slaState=="on_track"),escalated=rows.Where(x=>(string)x.status=="escalated").Select(x=>(Guid)x.id),aiHandled=items.Count(x=>(string)D(x).responsible=="ai"),humanNeeded=items.Count(x=>(string)D(x).responsible=="owner")},escalations=items.Where(x=>(string)D(x).status=="escalated")};}

    [HttpGet("chats")]
    public async Task<object> Chats([FromQuery]Guid? unitId,CancellationToken ct){var uid=UserId();var s=await Scope(uid,unitId,ct);await using var db=sql.Create();return await db.QueryAsync(DbProc.Call("usp_Owner_ListChats", new{units=DbProc.Csv(s.Units)}, ct));}

    public sealed record MisrouteRequest(Guid CaseId,Guid? CorrectedUnitId,string Reason);
    [HttpPost("misrouting")]
    public async Task<object> Misrouting([FromBody]MisrouteRequest r,CancellationToken ct){var uid=UserId();if(r.Reason.Trim().Length is <5 or >1000)return BadRequest();await using var db=sql.Create();var c=await db.QuerySingleOrDefaultAsync(DbProc.Call("usp_Owner_GetCaseRouting", r, ct))??throw new NotFoundException();if(!await permissions.OwnsServiceUnitAsync(uid,(Guid?)c.service_unit_id,ct)&&!await permissions.IsManagerAsync(uid,ct))throw new ForbiddenException();await db.ExecuteAsync(DbProc.Call("usp_Owner_InsertRoutingFeedback", new{r.CaseId,uid,original=(Guid?)c.service_unit_id,r.CorrectedUnitId,service=(string?)c.routing_service_code,topic=(string?)c.routing_topic,r.Reason}, ct));var reassigned=r.CorrectedUnitId is not null&&r.CorrectedUnitId!=(Guid?)c.service_unit_id;if(reassigned)await db.ExecuteAsync(DbProc.Call("usp_Owner_ReassignMisroute", new{r.CaseId,r.CorrectedUnitId,uid,reason=$"Reassigned by service owner: {r.Reason}"}, ct));await db.ExecuteAsync(DbProc.Call("usp_Owner_InsertRoutingSignal", new{r.CaseId,original=(Guid?)c.service_unit_id,r.CorrectedUnitId,topic=(string?)c.routing_topic,service=(string?)c.routing_service_code,r.Reason,outcome=reassigned?"reassigned":"reported"}, ct));return new{ok=true,reassigned};}

    [HttpGet("dashboard")]
    public async Task<object> Dashboard([FromQuery]Guid? unitId,[FromQuery]int days=30,CancellationToken ct=default){var uid=UserId();var s=await Scope(uid,unitId,ct);days=Math.Clamp(days,1,365);await using var db=sql.Create();var rows=(await db.QueryAsync(DbProc.Call("usp_Owner_ListDashboardCases", new{units=DbProc.Csv(s.Units),uid,days}, ct))).ToArray();int C(IEnumerable<string> states)=>rows.Count(x=>states.Contains((string)x.status));return new{unitIds=s.Units,since=DateTimeOffset.UtcNow.AddDays(-days),byType=new{query=rows.Count(x=>(string)x.case_type=="query"),complaint=rows.Count(x=>(string)x.case_type=="complaint"),suggestion=rows.Count(x=>(string)x.case_type=="suggestion"),alert=rows.Count(x=>(string)x.case_type=="alert"),service_request=rows.Count(x=>(string)x.case_type=="service_request")},byStatus=new{open=C(Open),inProgress=C(Progress),waitingStudent=C(Waiting),resolved=C(["resolved"]),closed=C(["closed"])},total=rows.Length,attention=C(Open),recent=rows.OrderByDescending(x=>(DateTimeOffset?)x.last_activity_at??(DateTimeOffset)x.created_at).Take(8)};}
}
